namespace RonSijm.FluidHumidifier.Factories.Lambda;

public class CapacityProviderFactory(string resourceName = null, Action<Humidifier.Lambda.CapacityProvider> factoryAction = null) : ResourceFactory<Humidifier.Lambda.CapacityProvider>(resourceName)
{

    internal InnerCapacityProviderCapacityProviderScalingConfigFactory CapacityProviderScalingConfigFactory { get; set; }

    internal InnerCapacityProviderCapacityProviderVpcConfigFactory VpcConfigFactory { get; set; }

    internal InnerCapacityProviderPropagateTagsConfigFactory PropagateTagsFactory { get; set; }

    internal InnerCapacityProviderInstanceRequirementsFactory InstanceRequirementsFactory { get; set; }

    internal InnerCapacityProviderCapacityProviderPermissionsConfigFactory PermissionsConfigFactory { get; set; }

    internal InnerCapacityProviderCapacityProviderTelemetryConfigFactory TelemetryConfigFactory { get; set; }

    protected override Humidifier.Lambda.CapacityProvider Create()
    {
        var capacityProviderResult = CreateCapacityProvider();
        factoryAction?.Invoke(capacityProviderResult);

        return capacityProviderResult;
    }

    private Humidifier.Lambda.CapacityProvider CreateCapacityProvider()
    {
        var capacityProviderResult = new Humidifier.Lambda.CapacityProvider
        {
            GivenName = InputResourceName,
        };

        return capacityProviderResult;
    }
    public override void CreateChildren(Humidifier.Lambda.CapacityProvider result)
    {
        base.CreateChildren(result);

        result.CapacityProviderScalingConfig ??= CapacityProviderScalingConfigFactory?.Build();
        result.VpcConfig ??= VpcConfigFactory?.Build();
        result.PropagateTags ??= PropagateTagsFactory?.Build();
        result.InstanceRequirements ??= InstanceRequirementsFactory?.Build();
        result.PermissionsConfig ??= PermissionsConfigFactory?.Build();
        result.TelemetryConfig ??= TelemetryConfigFactory?.Build();
    }

} // End Of Class

